int licznik = 0;
int liczba = 0;

int minimum, maksimum, jasnosc;

const byte segmenty[10] = {
  0b0000001, // 0
  0b1001111, // 1
  0b0010010, // 2
  0b0000110, // 3
  0b1001100, // 4
  0b0100100, // 5
  0b0100000, // 6
  0b0001111, // 7
  0b0000000, // 8
  0b0000100  // 9
};

void Znak(int numer) {
  byte wzor = segmenty[numer];

  for (int i = 0; i < 7; i++) {
    digitalWrite(i + 2, (wzor >> (6 - i)) & 1);
  }
}

void setup() {
  for (int i = 2; i <= 8; i++) {
    pinMode(i, OUTPUT);
  }

  pinMode(10, OUTPUT);
  pinMode(11, OUTPUT);

  digitalWrite(10, LOW);
  digitalWrite(11, LOW);

  minimum = analogRead(A0);
  maksimum = minimum;
}

void loop() {

  digitalWrite(11, LOW);
  Znak(liczba % 10);
  digitalWrite(10, HIGH);
  delay(2);
  digitalWrite(10, LOW);

  Znak((liczba / 10) % 10);
  digitalWrite(11, HIGH);
  delay(2);
  digitalWrite(11, LOW);

  licznik++;

  if (licznik >= 100) {
    jasnosc = analogRead(A0);

    if (jasnosc < minimum) minimum = jasnosc;
    if (jasnosc > maksimum) maksimum = jasnosc;

    if (maksimum > minimum) {
      liczba = map(jasnosc, minimum, maksimum, 0, 99);
    } else {
      liczba = 0;
    }

    liczba = constrain(liczba, 0, 99);
    licznik = 0;
  }
}
